def valid_length(pw):
    return 8 <= len(pw) <= 12

def valid_range(mark):
    return 0 <= mark <= 100

def valid_code(code):
    return len(code) == 4 and code[0].isalpha() and code[1:].isdigit()

print(valid_length("salam"), valid_length("tarbiyyah1"))
print(valid_range(101), valid_range(100))
print(valid_code("A123"), valid_code("123A"))

